insert into public.country_occupation_profiles (profile_key,country_code,canonical_career_id,official_title,official_code_system,official_code_version,official_unit_group_code,currency,registration_required,registration_authority,registration_url,publication_status,source_checked_at,updated_at) values ('AU:ux-designer','AU','ux-designer','UI / UX Designer','OSCA','2024 v1.0','2421','AUD',false,'No statutory registration; no direct current CSOL assessing-authority route is scored for ANZSCO 261113',null,'profile_ready','2026-08-09',now()) on conflict (profile_key) do update set official_title=excluded.official_title,official_code_system=excluded.official_code_system,official_code_version=excluded.official_code_version,official_unit_group_code=excluded.official_unit_group_code,currency=excluded.currency,registration_required=excluded.registration_required,registration_authority=excluded.registration_authority,registration_url=excluded.registration_url,publication_status=excluded.publication_status,source_checked_at=excluded.source_checked_at,updated_at=now();
insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,employment_total,median_weekly_earnings,median_hourly_earnings,annualised_median_salary,all_occupations_median_weekly,part_time_share_pct,female_share_pct,median_age,average_full_time_hours,vacancies_three_month_avg,vacancy_period,vacancy_yoy_pct,employment_growth_5y_pct,employment_growth_10y_pct,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values ('AU:ux-designer','2026-05-01',null,null,null,null,1852,null,null,null,null,1863,'2026-05-01',-8.05,15.07,25.88,0,0,5,0,13,0,5,0,5,28,'career-opportunity-v1','provisional',jsonb_build_object('classification_scope','Current OSCA 242132 UI / UX Designer is an exact canonical mapping and UX Designer is an explicit alternative title. ABS current correspondence maps it to ANZSCO 2022 261113 User Experience Designer.','labour_scope','The current JSA occupation-profile ingest is legacy ANZSCO-based and contains no exact six-digit 261113 User Experience Designer labour profile, so primary employment, demographics and earnings remain null.','legacy_scope_warning','The ingest legacy correspondence to ANZSCO 2013 v1.3 must not be treated as the current 261113 occupation.','vacancy_scope','Broader ANZSCO 2611 vacancies were 1863 in May 2026 versus 2026 in May 2025, about -8.05% year on year; no exact vacancy intensity or trend credit.','projection_scope','Broader ANZSCO 2611 projections are +15.07% to 2030 and +25.88% to 2035; partial growth credit only.','shortage_note','JSA 2025 OSL records current OSCA 242132 UI / UX Designer as No Shortage nationally.','visa_basis','The in-force Core Skills Occupation List uses ANZSCO as in force on 23 November 2022 and does not list 261113 User Experience Designer. Legacy proxy codes are not substituted, so visa credit is zero.','entry_level_basis','University of Canberra Bachelor of Design 113900B has a current Interaction Design specialist major including Human Factors, Front-end Web Design and Designing for UX; UQ Master of Interaction Design 080726K is a current two-year postgraduate interaction-design route.','score_note','Exact current classification is retained while labour and migration evidence are kept conservative where no exact current series or list entry exists.'),'2026-08-09') on conflict (profile_key,as_of_date) do update set employment_total=excluded.employment_total,median_weekly_earnings=excluded.median_weekly_earnings,median_hourly_earnings=excluded.median_hourly_earnings,annualised_median_salary=excluded.annualised_median_salary,all_occupations_median_weekly=excluded.all_occupations_median_weekly,part_time_share_pct=excluded.part_time_share_pct,female_share_pct=excluded.female_share_pct,median_age=excluded.median_age,average_full_time_hours=excluded.average_full_time_hours,vacancies_three_month_avg=excluded.vacancies_three_month_avg,vacancy_period=excluded.vacancy_period,vacancy_yoy_pct=excluded.vacancy_yoy_pct,employment_growth_5y_pct=excluded.employment_growth_5y_pct,employment_growth_10y_pct=excluded.employment_growth_10y_pct,shortage_component=excluded.shortage_component,vacancy_intensity_component=excluded.vacancy_intensity_component,employer_diversity_component=excluded.employer_diversity_component,vacancy_trend_component=excluded.vacancy_trend_component,entry_level_component=excluded.entry_level_component,salary_component=excluded.salary_component,growth_component=excluded.growth_component,visa_component=excluded.visa_component,entry_burden_component=excluded.entry_burden_component,opportunity_score=excluded.opportunity_score,score_methodology_version=excluded.score_methodology_version,score_status=excluded.score_status,score_evidence=excluded.score_evidence,source_checked_at=excluded.source_checked_at;
